    if depth > 3: return rng.choice([1, 1.0, True, 'a', None])
    choice = rng.choice(['dict','list','tuple','scalar'])
    if choice == 'dict':
        return {rng.choice(['a','b','c',1,True]): rand_val(depth+1) for _ in range(rng.randint(0,3))}
    if choice == 'list': return [rand_val(depth+1) for _ in range(rng.randint(0,3))]
    if choice == 'tuple': return tuple(rand_val(depth+1) for _ in range(rng.randint(0,3)))
    return rng.choice([1, 1.5, True, False, None, 'a', 'b'])

bad = 0
for i in range(20000):
    a = rand_val(); b = rand_val()
    # make them equal with some probability
    if rng.random() < 0.5:
        b = eval(repr(a)) if hasattr(repr(a), '__len__') else a  # deep-ish copy via repr may fail on tuples?
    try:
        eq = (a == b)
    except Exception:
        continue
    # canonical form
    def canon(x):
        if isinstance(x, dict):
            return ('dict', frozenset((k, canon(v)) for k, v in x.items()))
        if isinstance(x, (list, tuple)):
            return ('seq', type(x).__name__, tuple(canon(v) for v in x))
