import random
from etl.dedupe import dedupe

def naive(records, key=None):
    seen = []
    out = []
    for r in records:
        k = key(r) if key else r
        if not any(k == s for s in seen):
            seen.append(k)
            out.append(r)
    return out

rng = random.Random(7)

def rand_val(depth=0):
    if depth >= 3:
        return rng.choice([1, 1.5, True, False, None, 'a', 'b', 2, 1.0])
    ch = rng.choice(['dict','list','tuple','scalar','scalar'])
    if ch == 'dict':
        keys = rng.sample(['a','b','c','d','e'], rng.randint(0,3))
        d = {}
        for k in keys:
            d[k] = rand_val(depth+1)
        return d
    if ch == 'list':
        return [rand_val(depth+1) for _ in range(rng.randint(0,3))]
    if ch == 'tuple':
        return tuple(rand_val(depth+1) for _ in range(rng.randint(0,3)))
    return rng.choice([1, 1.5, True, False, None, 'a', 'b', 2, 1.0, 0.5])

mismatch = 0
for trial in range(300):
    records = []
    for i in range(rng.randint(5, 60)):
        records.append(rand_val())
    # ensure duplicates
    if rng.random() < 0.7:
        records[rng.randint(0, len(records)-1)] = records[0]
    mode = rng.choice(['none','identity','dictkey','listkey','tuplekey','nestedkey'])
    if mode == 'none':
        k = None
    elif mode == 'identity': k = lambda r: r
    elif mode == 'dictkey': k = lambda r: {'t': type(r).__name__, 'v': r if isinstance(r, (str,int,float,bool,type(None))) else None}
    elif mode == 'listkey': k = lambda r: [r] if isinstance(r, (list, dict)) else ['other', r]
    elif mode == 'tuplekey': k = lambda r: (r, 1) if isinstance(r, (list, dict)) else ('x', r)
    elif mode == 'nestedkey': k = lambda r: {'a': r, 'b': [r, 1]} if isinstance(r, (list, dict)) else r
    try:
        expected = naive(records, key=k)
        actual = dedupe(records, key=k)
    except Exception as e:
        print("ERROR mode", mode); raise
    if len(expected) != len(actual) or [id(r) for r in expected] != [id(r) for r in actual]:
        # compare by equality of contents since same objects
        if expected != actual:
            mismatch += 1
            print("MISMATCH mode", mode, "\n exp:", expected, "\n act:", actual)
print("mismatches:", mismatch)
